var SITES = [{"id":"missav","n":"MissAV","base":"https://missav.ai","e":[{"t":"最近更新","u":"/cn/new","r":"update"},{"t":"本周热门","u":"/cn/weekly-hot","r":"week"},{"t":"本月热门","u":"/cn/monthly-hot","r":"month"},{"t":"今日热门","u":"/cn/today-hot","r":"all"},{"t":"新片发布","u":"/cn/release"},{"t":"中文字幕","u":"/cn/chinese-subtitle"},{"t":"无码流出","u":"/cn/uncensored-leak"},{"t":"人妻","u":"/cn/genres/%E4%BA%BA%E5%A6%BB"},{"t":"巨乳","u":"/cn/genres/%E5%B7%A8%E4%B9%B3"},{"t":"熟女","u":"/cn/genres/%E7%86%9F%E5%A5%B3"},{"t":"素人","u":"/cn/genres/%E7%B4%A0%E4%BA%BA"},{"t":"NTR","u":"/cn/genres/NTR"}]}];

function strip(u){var i=String(u).indexOf('#');return i<0?String(u):String(u).substring(0,i)}
function abs(b,u){if(!u)return'';u=String(u).replace(/^\s+|\s+$/g,'');if(u.indexOf('http')===0)return u;if(u.charAt(0)==='/')return b+u;return b+'/'+u}
function firstLine(u){var a=String(u||'').split('\n');for(var i=0;i<a.length;i++){if(a[i].replace(/\s/g,''))return a[i].replace(/^\s+|\s+$/g,'')}return''}
function pick(J,rule,el){if(!rule)return'';try{return el?String(J.getString(rule,el)):String(J.getString(rule))}catch(e){return''}}
function pickUrl(J,rule,el){return firstLine(pick(J,rule,el))}
function loggedIn(J){
  try{ return String(J.getCookie(SITES[0].base,'missav_session')).length>0 }catch(e){ return false }
}
function exploreAll(J){
  var s=SITES[0],out=[];
  if(!s||!s.e)return '[]';
  for(var i=0;i<s.e.length;i++){
    var e=s.e[i];
    out.push({title:e.t,url:abs(s.base,e.u)+'?page={{page}}#'+s.id,rank:e.r||''});
  }
  if(loggedIn(J)) out.push({title:'我的收藏',url:abs(s.base,'/cn/saved')+'?page={{page}}#'+s.id,rank:''});
  return JSON.stringify(out);
}
function infoLine(J,label){
  var els=J.getElements('class.text-secondary'),v='';
  for(var i=0;i<els.size();i++){
    var t=String(els.get(i).text()).replace(/\s+/g,' ').trim();
    if(t.indexOf(label)===0)v=t;
  }
  return v;
}
function genresOf(J){
  var els=J.getElements('tag.a'),out=[];
  for(var i=0;i<els.size();i++){
    var h=String(els.get(i).attr('href')||'');
    if(h.indexOf('/cn/genres/')>0)out.push(String(els.get(i).text()).trim());
  }
  return out.join(',');
}
function playUrl(h){
  var m=String(h||'').match(/surrit\.com\W+([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/);
  return m?'https://surrit.com/'+m[1]+'/playlist.m3u8':'';
}

