@js:function login(){
  var m = source.getLoginInfoMap();
  var em = String(m.get('账号') || '').replace(/^\s+|\s+$/g, '');
  var pw = String(m.get('密码') || '');
  if (!em || !pw) throw new Error('请先填写 MissAV 账号与密码');
  var base = SITES[0].base;
  var hd = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36', 'Accept': 'application/json, text/plain, */*', 'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8', 'Content-Type': 'application/json', 'Origin': base, 'Referer': base + '/cn/new'};
  var opt = JSON.stringify({method: 'POST', body: JSON.stringify({email: em, password: pw, remember: true}), headers: hd});
  var resp = String(java.ajax(base + '/cn/api/login,' + opt));
  var d = null;
  try { d = JSON.parse(resp) } catch (e) {}
  if (!d) throw new Error('登录失败：站点返回的不是 JSON（可能被 Cloudflare 拦截或请求过频），请稍后重试');
  if (!d.user) throw new Error('登录失败：' + resp.substring(0, 140));
  source.refreshExplore();
  return em;
}
